/* Selectable places, generated by tools/gen_maps.py. */
#pragma once
#include <stdint.h>

typedef struct {
    char iata[4];
    const char *city;
    float lat, lon;
} zone_airport_t;

typedef struct {
    const char *title;              /* top bar and place list */
    const char *ref;                /* distances are given from this city */
    float lat0, lat1, lon0, lon1;   /* map extent */
    float ref_lat, ref_lon;
    float km_lon;                   /* km per degree of longitude at the map centre */
    zone_airport_t apt[3];          /* apt[0] is the main airport (range rings) */
    int n_apt;
    const uint8_t *map;             /* 800x440 RGB565, zlib */
    unsigned map_len;
} zone_t;

extern const zone_t zones[];
extern const int zones_n;
